// Revamp — new enquiry workflow (n8n Code node)
//
// A faithful port of the deterministic rules in src/ai/rules.ts. It returns the
// same { steps, effects } contract the app's local workflow engine produces, so
// Revamp behaves identically whether this runs here or in the browser.

const payload = $json.body ?? $json;
const enquiry = payload.input?.enquiry;

if (!enquiry) {
  return [{ json: { steps: [{ name: 'Webhook', status: 'failed', detail: 'No enquiry in payload' }], effects: [] } }];
}

const text = `${enquiry.subject}\n${enquiry.body}`;
const hay = text.toLowerCase().replace(/\s+/g, ' ');
const now = new Date().toISOString();

const CATEGORIES = [
  { category: 'sales_enquiry', label: 'Sales enquiry', keywords: [['quote',3],['pricing',3],['price',2],['cost',2],['proposal',3],['redesign',2],['new website',3],['project',1],['budget',3],['looking for help',3],['interested in',2],['engage',2],['statement of work',3],['rfp',3],['tender',3],['scope',1]] },
  { category: 'support_issue', label: 'Support issue', keywords: [['broken',3],['not working',4],['error',3],['bug',3],['outage',5],['down',3],['cannot',2],["can't",2],['failing',3],['crash',4],['urgent',2],['issue',2],['fault',3],['timeout',3],['503',4],['data loss',5],['locked out',4]] },
  { category: 'billing_question', label: 'Billing question', keywords: [['invoice',4],['billing',4],['overcharged',5],['refund',4],['payment',3],['vat',3],['receipt',3],['direct debit',4],['subscription renewal',3],['purchase order',3]] },
  { category: 'partnership', label: 'Partnership enquiry', keywords: [['partnership',5],['partner',3],['reseller',4],['referral',3],['collaborate',3],['white label',4],['integration partner',4]] },
  { category: 'recruitment', label: 'Recruitment', keywords: [['cv',4],['resume',4],['vacancy',4],['job',3],['role',1],['apply',3],['application for',3],['hiring',3],['portfolio',2]] },
];

const scores = CATEGORIES.map((entry) => {
  const matched = entry.keywords.filter(([word]) => hay.includes(word));
  return { category: entry.category, label: entry.label, matched: matched.map(([w]) => w), score: matched.reduce((t, [, w]) => t + w, 0) };
}).sort((a, b) => b.score - a.score || a.category.localeCompare(b.category));

const best = scores[0].score === 0 ? { category: 'general', label: 'General enquiry', score: 0, matched: [] } : scores[0];

const URGENCY = [['urgent',3],['asap',3],['immediately',3],['critical',4],['outage',4],['down',2],['deadline',2],['escalate',3],['losing',2],['blocked',2],['today',2],['emergency',4],['production',2],['data loss',4]];
const urgencyMatched = URGENCY.filter(([word]) => hay.includes(word));
const urgency = urgencyMatched.reduce((t, [, w]) => t + w, 0);

const employeeMatch = hay.match(/(?:around |about |approximately |roughly |over |we have )?(\d[\d,]*)\s*(?:\+)?\s*(?:employees|staff|people|headcount|seats|users)/);
const employees = employeeMatch ? Number(employeeMatch[1].replace(/,/g, '')) : null;

const MONTHS = ['january','february','march','april','may','june','july','august','september','october','november','december'];
const monthHit = MONTHS.find((m) => hay.includes(m));
const quarterMatch = hay.match(/\bq([1-4])\b/);
let deadline = monthHit ? monthHit[0].toUpperCase() + monthHit.slice(1) : null;
if (!deadline && quarterMatch) deadline = `Q${quarterMatch[1]}`;
if (!deadline && /(asap|as soon as possible|immediately)/.test(hay)) deadline = 'Immediate';

const SERVICES = [
  [/website redesign|redesign(ing)? (our|the|your)? ?website|site redesign/, 'Website redesign', 9000],
  [/e-?commerce|online (shop|store)|checkout/, 'E-commerce build', 22000],
  [/mobile app|ios app|android app/, 'Mobile application', 30000],
  [/brand(ing)?|logo|identity/, 'Brand identity', 7000],
  [/seo|search engine/, 'SEO engagement', 6000],
  [/migration|migrate/, 'Platform migration', 18000],
  [/support (contract|retainer)|maintenance/, 'Support retainer', 12000],
  [/integration|api work/, 'Systems integration', 14000],
];
const serviceHit = SERVICES.find(([pattern]) => pattern.test(hay));
const service = serviceHit ? serviceHit[1] : null;

const budgetMatch = hay.match(/(?:£|gbp\s?)([\d,]+)(?:\s*(?:k|,000))?/);
const companyMatch = text.match(/\b([A-Z][A-Za-z&.'-]*(?:\s+[A-Z][A-Za-z&.'-]*)*)\s+(Ltd|Limited|LLP|PLC|Group|Holdings|Partners)\b/);

const extracted = {
  company: companyMatch ? `${companyMatch[1]} ${companyMatch[2]}` : (enquiry.company ?? null),
  employees,
  service,
  deadline,
  budget: budgetMatch ? budgetMatch[0].trim() : null,
  location: null,
};

let estimatedValue = null;
if (best.category === 'sales_enquiry' || best.category === 'partnership') {
  const base = serviceHit ? serviceHit[2] : 8000;
  const size = employees ?? 40;
  const multiplier = size >= 500 ? 2.4 : size >= 250 ? 1.9 : size >= 100 ? 1.35 : size >= 25 ? 1 : 0.7;
  const mid = base * multiplier;
  const round500 = (n) => Math.round(n / 500) * 500;
  estimatedValue = { min: round500(mid * 0.8), max: round500(mid * 1.2) };
}

let points = urgency;
if (best.category === 'support_issue') points += 2;
if (best.category === 'billing_question') points += 1;
if (best.category === 'recruitment') points -= 2;
const maxValue = estimatedValue ? estimatedValue.max : 0;
if (maxValue >= 25000) points += 4; else if (maxValue >= 10000) points += 3; else if (maxValue >= 4000) points += 1;
if ((employees ?? 0) >= 250) points += 2; else if ((employees ?? 0) >= 100) points += 1;
if (enquiry.customerId) points += 1;
if (deadline) points += 1;

const priority = points >= 9 ? 'urgent' : points >= 5 ? 'high' : points >= 2 ? 'medium' : 'low';
const SLA = { urgent: 1, high: 4, medium: 24, low: 72 };
const slaHours = SLA[priority];

const INTENTS = {
  sales_enquiry: 'Requesting pricing and availability for a new engagement',
  support_issue: 'Reporting a problem with a live service',
  billing_question: 'Querying an invoice or payment',
  partnership: 'Proposing a commercial partnership',
  recruitment: 'Applying for a role',
  general: 'General contact — intent unclear from the message',
};

const ACTIONS = {
  sales_enquiry: `Contact within ${slaHours} hours with an indicative price and a discovery call slot.`,
  support_issue: `Acknowledge within ${slaHours} hours and assign to support triage.`,
  billing_question: `Route to finance and confirm the invoice position within ${slaHours} hours.`,
  partnership: 'Send the partner overview pack and book an introductory call.',
  recruitment: 'Forward to the hiring inbox. No commercial follow-up needed.',
  general: `Reply within ${slaHours} hours to clarify what the sender needs.`,
};

const margin = best.score - (scores[1] ? scores[1].score : 0);
const confidence = best.score === 0
  ? 0.42
  : Math.round(Math.min(0.55 + Math.min(margin / 8, 1) * 0.3 + Math.min(best.matched.length / 4, 1) * 0.14, 0.97) * 100) / 100;

const reasoning = [];
if (best.matched.length) reasoning.push(`Matched ${best.matched.length} ${best.label.toLowerCase()} signals: ${best.matched.slice(0, 4).join(', ')}.`);
if (urgencyMatched.length) reasoning.push(`Urgency language detected: ${urgencyMatched.slice(0, 3).map(([w]) => w).join(', ')}.`);
if (employees) reasoning.push(`Company size of ${employees} staff raises the expected deal band.`);
if (deadline) reasoning.push(`A target of ${deadline} was stated, which adds time pressure.`);
reasoning.push('Executed by n8n.');

const analysis = {
  category: best.category,
  categoryLabel: best.label,
  intent: INTENTS[best.category],
  priority,
  confidence,
  estimatedValue,
  slaHours,
  recommendedAction: ACTIONS[best.category],
  reasoning,
  extracted,
  providerId: 'n8n',
  analysedAt: now,
};

const OWNERS = { sales_enquiry: 'Priya Raman', support_issue: 'Tom Beckett', billing_question: 'Dana Fowler', partnership: 'Alex Whitmore', recruitment: 'Hiring inbox', general: 'Alex Whitmore' };
const id = (prefix) => `${prefix}_n8n_${Date.now().toString(36)}${Math.floor(Math.random() * 1e6).toString(36)}`;

const task = {
  id: id('task'),
  title: `Follow up with ${extracted.company ?? enquiry.company}`,
  detail: analysis.recommendedAction,
  priority,
  assignee: OWNERS[best.category],
  dueAt: new Date(Date.now() + slaHours * 3600000).toISOString(),
  source: 'n8n enquiry workflow',
  status: 'open',
  linkedEnquiryId: enquiry.id,
  createdAt: now,
  completedAt: null,
};

const firstName = String(enquiry.senderName || 'there').split(' ')[0];
const money = (n) => `£${n.toLocaleString('en-GB')}`;
const draftLines = [`Hi ${firstName},`, ''];
if (best.category === 'sales_enquiry') {
  draftLines.push(
    `Thanks for getting in touch about ${service ? service.toLowerCase() : 'your project'}${extracted.company ? ` at ${extracted.company}` : ''}. It sounds like a good fit for the work we do.`, '',
    estimatedValue ? `• Indicative range: projects of this shape typically land between ${money(estimatedValue.min)} and ${money(estimatedValue.max)}, confirmed after a scoping call.` : '• Indicative range: confirmed after a scoping call.',
    '• Next step: a 30-minute discovery call to confirm scope, integrations and success measures.',
    `• Timeline: ${deadline ? `we can work back from ${deadline}` : 'we can share an outline schedule after the call'}.`, '',
    'Would either of the next two working days suit you for that call?');
} else if (best.category === 'support_issue') {
  draftLines.push(`Thanks for flagging this, and sorry for the disruption. I have logged it as a ${priority} priority issue and it is with our team now.`, '', `• We will confirm the cause within ${slaHours} hour${slaHours === 1 ? '' : 's'}.`, '• I will write to you again as soon as we have a fix or a workaround.');
} else {
  draftLines.push('Thanks for getting in touch. I have passed this to the right team and someone will come back to you shortly.');
}
draftLines.push('', 'Best regards,', 'Alex Whitmore', 'Northwind Studio');

const draft = {
  body: draftLines.join('\n'),
  tone: best.category === 'sales_enquiry' ? 'consultative' : best.category === 'support_issue' || best.category === 'billing_question' ? 'apologetic' : 'professional',
  generatedAt: now,
  providerId: 'n8n',
  approved: false,
  edited: false,
};

const activity = (kind, message, detail) => ({
  type: 'activity',
  activity: { id: id('act'), at: new Date().toISOString(), kind, actor: 'automation', message, detail, entityId: enquiry.id },
});

const effects = [
  { type: 'enquiry_analysed', enquiryId: enquiry.id, analysis },
  activity('ai_analysis', `n8n classified enquiry from ${enquiry.company} as ${best.label}`, analysis.intent),
  activity('ai_analysis', `Priority set to ${priority.toUpperCase()}`, `Respond within ${slaHours}h`),
  activity('ai_extraction', 'Customer information extracted', Object.entries(extracted).filter(([, v]) => v !== null).map(([k, v]) => `${k}: ${v}`).join(', ')),
  { type: 'task_created', task },
  activity('task_created', `Follow-up task created: ${task.title}`, `Assigned to ${task.assignee}`),
  { type: 'draft_generated', enquiryId: enquiry.id, draft },
  activity('draft_generated', `Response draft generated for ${enquiry.company}`, `Tone: ${draft.tone}`),
  { type: 'enquiry_status', enquiryId: enquiry.id, status: 'awaiting_approval' },
  activity('approval_pending', 'Awaiting human approval', 'No message is sent until a person approves the draft.'),
];

const steps = [
  { name: 'Analyse with AI', status: 'success', detail: `Classified as ${best.label}` },
  { name: 'Determine priority', status: 'success', detail: `${priority.toUpperCase()} — respond within ${slaHours}h` },
  { name: 'Extract customer information', status: 'success', detail: `${Object.values(extracted).filter((v) => v !== null).length} fields found` },
  { name: 'Create follow-up task', status: 'success', detail: `Assigned to ${task.assignee}` },
  { name: 'Generate response', status: 'success', detail: `${draft.tone} draft` },
  { name: 'Write activity log', status: 'success', detail: `${effects.filter((e) => e.type === 'activity').length} entries recorded` },
];

return [{ json: { steps, effects } }];
